param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks")
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop"
$catalog=Join-Path $BenchmarkRepo "catalog\global";$report=Join-Path $BenchmarkRepo "reports\v0.40.0";$required=@((Join-Path $catalog "GLOBAL-BENCHMARK-REGISTRY-v0.40.0.csv"),(Join-Path $catalog "GLOBAL-NORMALIZED-TRUST-v0.40.0.csv"),(Join-Path $catalog "GLOBAL-FAMILY-PORTFOLIO-v0.40.0.csv"),(Join-Path $catalog "GLOBAL-OPEN-CHALLENGES-v0.40.0.csv"),(Join-Path $catalog "V2-DEFERRED-WORK-v0.40.0.csv"),(Join-Path $catalog "GLOBAL-LICENCE-PROVENANCE-AUDIT-v0.40.0.csv"),(Join-Path $report "V1-RELEASE-READINESS-v0.40.0.csv"),(Join-Path $report "RELEASE-FILE-MANIFEST-v0.40.0.csv"));foreach($path in $required){if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw ("Required closure artifact missing: "+$path)}}
$registry=@(Import-Csv -LiteralPath $required[0]);$trust=@(Import-Csv -LiteralPath $required[1]);$portfolio=@(Import-Csv -LiteralPath $required[2]);$challenges=@(Import-Csv -LiteralPath $required[3]);$v2=@(Import-Csv -LiteralPath $required[4]);if($registry.Count -ne 7905 -or $trust.Count -ne 7905){throw "Row invariant failed."};if(@($registry.global_instance_id|Sort-Object -Unique).Count -ne 7905){throw "Global ID uniqueness failed."};if($challenges.Count -ne 125){throw "Challenge invariant failed."};$multi=$portfolio|Where-Object{$_.family -eq "MULTILSB"};if($null -eq $multi -or [int]$multi.normalized_source_instances -ne 120 -or $multi.v1_disposition -ne "DEFERRED_V2_MODEL_EXTENSION"){throw "MULTILSB disposition failed."};if(@($v2|Where-Object{$_.scope -eq "MULTILSB"}).Count -ne 1){throw "MULTILSB v2 backlog record missing."}
$manifest=@(Import-Csv -LiteralPath $required[7]);foreach($entry in $manifest){$path=Join-Path $BenchmarkRepo $entry.path;if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw ("Manifest file missing: "+$entry.path)};if((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower() -ne $entry.sha256){throw ("Manifest hash mismatch: "+$entry.path)}}
Write-Host "CORPUS_EVIDENCE_CLOSURE_V0.40.0_VALID";Write-Host "REGISTRY_ROWS|7905";Write-Host "GLOBAL_IDS|UNIQUE";Write-Host "ACTIONABLE_CHALLENGES|125";Write-Host "MULTILSB_CANONICAL|0";Write-Host "V2_BACKLOG|READY";Write-Host "V1_RELEASE_GATE|READY_WITH_DOCUMENTED_OPEN_ITEMS"
